\label{thm:SZ}
Let $(M,g)$ be a complete Riemannian manifold of non-negative Ricci curvature.
Then we have the following:
\begin{enumerate}\setlength{\itemsep}{+0.7mm}
\item Let $u:M\times (-\infty,0]\to (0,\infty)$ be a positive ancient solution to the heat equation.
If
\begin{equation*}
u(x,t)=\exp\left[o\left(d(x)+\sqrt{\vert t\vert}\right)\right]
\end{equation*}
near infinity, then $u$ must be constant.
Here $d(x)$ denotes the Riemannian distance from a fixed point; \label{enum:positive growth}
\item let $u:M\times (-\infty,0]\to \mathbb{R}$ be an ancient solution to the heat equation.
If
\begin{equation*}
u(x,t)=o\left(d(x)+\sqrt{\vert t\vert}\right)
\end{equation*}
near infinity, then $u$ is constant. \label{enum:usual growth}
\end{enumerate}

\label{thm:main result in KuS}
Let $(M,g(\tau))_{\tau \in [0,\infty)}$ be an admissible, complete backward super Ricci flow.
We assume
\begin{equation*}
\mathcal{D}(V)\geq 0,\quad \mathcal{H}(V) \geq -\frac{H}{\tau},\quad H\geq 0
\end{equation*}
for all vector fields $V$.
Then we have the following:
\begin{enumerate}\setlength{\itemsep}{+0.7mm}
\item Let $u:M\times [0,\infty)\to (0,\infty)$ be a positive solution to backward heat equation.
If
\begin{equation*}\label{eq:positive growth}
u(x,\tau)=\exp\left[o\left(\mathfrak{d}(x,\tau)+\sqrt{\tau}\right)\right]
\end{equation*}
near infinity, then $u$ is constant.
Here $\mathfrak{d}(x,\tau)$ is defined by
\begin{equation*}
\mathfrak{d}(x,\tau):=\sqrt{4\tau\,\ell(x,\tau)};
\end{equation*}                   
\item let $u:M\times [0,\infty)\to \mathbb{R}$ be a solution to backward heat equation.
If
\begin{equation*}\label{eq:usual growth}
u(x,\tau)=o\left(\mathfrak{d}(x,\tau)+\sqrt{\tau}\right)
\end{equation*}
near infinity, then $u$ is constant.                     
\end{enumerate}

\label{thm:main1}
Let $(M,g(\tau))_{\tau \in [0,\infty)}$ be an admissible, complete backward super Ricci flow.
We assume
\begin{equation}\label{eq:main assumption}
\mathcal{D}(V)\geq 0,\quad \mathcal{H}(V) \geq -\frac{H}{\tau},\quad H\geq 0
\end{equation}
for all vector fields $V$.
Let $(N,\mathfrak{g})$ be a complete, simply connected Riemannian manifold with $\sec \leq 0$.
Let $u:M\times [0,\infty)\to N$ be a solution to backward harmonic map heat flow.
If
\begin{equation*}
\rho(u(x,\tau))=o\left(\mathfrak{d}(x,\tau)+\sqrt{\tau}\right)
\end{equation*}
near infinity, then $u$ is constant.
Here $\rho:N\to \mathbb{R}$ is the Riemannian distance function from a fixed point $y_0 \in N$.

\label{thm:main2}
Let $(M,g(\tau))_{\tau \in [0,\infty)}$ be an admissible, complete backward super Ricci flow.
We assume
\begin{equation}\label{eq:main assumption2}
\mathcal{D}(V)\geq 0,\quad \mathcal{H}(V) \geq -\frac{H}{\tau},\quad H\geq 0
\end{equation}
for all vector fields $V$.
Let $(N,\mathfrak{g})$ be a complete Riemannian manifold with $\sec \leq \kappa$ for $\kappa>0$.
Assume that an open geodesic ball $B_{\pi/2\sqrt{\kappa}}(y_0)$ of radius $\pi/2\sqrt{\kappa}$ centered at $y_0$ in $N$ does not meet the cut locus $\mathrm{Cut}\,(y_0)$ of $y_0$.
Let $u:M\times [0,\infty)\to N$ be a solution to backward harmonic map heat flow.
If the image of $u$ is contained in $B_{\pi/2\sqrt{\kappa}}(y_0)$,
and if $u$ satisfies
\begin{equation*}\label{eq:growth main2}
\frac{1}{\cos \sqrt{\kappa}\rho(u(x,\tau))}=o\left(\mathfrak{d}(x,\tau)^{1/2}+\tau^{1/4}\right)
\end{equation*}
near infinity, then $u$ is constant.

\label{lem:reduced heat estimate2}
Let $K\geq 0$.
We assume
\begin{equation*}\label{eq:assume reduced heat estimate2}
\mathcal{D}(V) \geq -2K\left(H + \Vert V \Vert^2\right),\quad H\geq 0
\end{equation*}
for all vector fields $V$.
Then at $(\overline{x},\overline{\tau})$ we have
\begin{equation*}
(\Delta+\partial_\tau)\overline{L} \leq 2m+2K \overline{L}.
\end{equation*}

\label{lem:reduced gradient estimate}
We assume
\begin{equation*}\label{eq:assumption rge}
\mathcal{H}(V) \geq -\frac{H}{\tau},\quad H\geq 0
\end{equation*}
for all vector fields $V$.
Then at $(\overline{x},\overline{\tau})$ we have
\begin{equation*}
\Vert \nabla \mathfrak{d} \Vert^2\leq 3.
\end{equation*}

\label{thm:gradient1}
For $K\geq 0$,
let $(M,g(\tau))_{\tau \in [0,\infty)}$ be an $m$-dimensional, admissible, complete backward $(-K)$-super Ricci flow,
namely,
\begin{equation*}\label{eq:KsRF}
\operatorname{Ric} \geq h-K g.
\end{equation*}
We assume 
\begin{equation}\label{eq:Kmain assumption}
\mathcal{D}(V)\geq -2K\left(H+\Vert V\Vert^2   \right),\quad \mathcal{H}(V) \geq -\frac{H}{\tau},\quad H\geq 0
\end{equation}
for all vector fields $V$.
Let $(N,\mathfrak{g})$ stand for a complete, simply connected Riemannian manifold with $\sec \leq 0$.
For a fixed $y_0\in N$,
let $\rho:N\to \mathbb{R}$ be the Riemannian distance function from $y_0$.
Let $u:M\times [0,\infty)\to N$ be a solution to backward harmonic map heat flow.
For $R,T>0$ and $A>0$,
we suppose $2\rho \circ u\leq A$ on
\begin{equation*}
Q_{R,T}:=\left\{\,(x,\tau)\in M\times \left(0,T\right] \,\,\, \middle|\,\,\, \mathfrak{d}(x,\tau)\leq R  \,\right\}.
\end{equation*}
Then there exists a positive constant $C_{m}>0$ depending only on $m$ such that on $Q_{R/2,T/4}$,
\begin{equation*}
\frac{\Vert du \Vert}{A^2-\rho^2 \circ u}\leq \frac{C_m}{A} \left( \frac{1}{R}+\frac{1}{\sqrt{T}}+\sqrt{K}  \right).
\end{equation*}

\label{lem:easy}
\begin{align*}
(\Delta+\partial_{\tau}) \Vert du\Vert^2 =2\Vert \nabla du\Vert^2&+2\sum^{m}_{i=1}\mathfrak{g}(du(\mathcal{R}(e_i)),du(e_i))\\
                                                 &-2\sum^{m}_{i,j=1}\mathfrak{g}(R(du(e_i),du(e_j))du(e_j),du(e_i)),
\end{align*}
where $\mathcal{R}:=\operatorname{Ric}-h$,
and $\{e_i\}^{m}_{i=1}$ is an orthonormal frame on $M$ at some fixed time.

\label{lem:simple}
Let $(N,\mathfrak{g})$ be simply connected, and $\sec \leq 0$.
For $A>0$, we assume $2\rho\circ u\leq A$.
Set
\begin{equation}\label{eq:key function}
w:=\frac{\Vert du\Vert^2}{(A^2-\rho^2 \circ u)^2}.
\end{equation}
Then we have
\begin{align*}
(\Delta+\partial_{\tau}) w-2\frac{g(\nabla w,\nabla (\rho^2\circ u))}{A^2-\rho^2 \circ u}&\geq 4(A^2-\rho^2 \circ u)w^2\\
      &\quad +\frac{2}{(A^2-\rho^2 \circ u)^2}\sum^{m}_{i=1}\mathfrak{g}(du(\mathcal{R}(e_i)),du(e_i)).
\end{align*}

By straightforward computations,
\begin{align*}
\nabla w&=\frac{\nabla \Vert du\Vert^2}{(A^2-\rho^2 \circ u)^2}+2\frac{\Vert du\Vert^2~\nabla (\rho^2 \circ u)}{(A^2-\rho^2 \circ u)^3},\\
\Delta w&=\frac{\Delta \Vert du\Vert^2}{(A^2-\rho^2 \circ u)^2}+\frac{4g(\nabla \Vert du\Vert^2,\nabla (\rho^2 \circ u))}{(A^2-\rho^2 \circ u)^3}+\frac{2\Vert du\Vert^2~ \Delta (\rho^2 \circ u)}{(A^2-\rho^2 \circ u)^3}+\frac{6\Vert \nabla (\rho^2 \circ u) \Vert^2~\Vert du\Vert^2}{(A^2-\rho^2 \circ u)^4}\\
                &=\frac{2g(\nabla w,\nabla (\rho^2\circ u))}{A^2-\rho^2 \circ u}+\frac{2\Vert du\Vert^2~ \Delta (\rho^2 \circ u)}{(A^2-\rho^2 \circ u)^3}+\frac{\Delta \Vert du\Vert^2}{(A^2-\rho^2 \circ u)^2}\\
                &\quad +\frac{2g(\nabla \Vert du\Vert^2,\nabla (\rho^2 \circ u))}{(A^2-\rho^2 \circ u)^3}+\frac{2\Vert \nabla (\rho^2 \circ u) \Vert^2~\Vert du\Vert^2}{(A^2-\rho^2 \circ u)^4},\\
\partial_{\tau} w&=\frac{\partial_{\tau} \Vert du\Vert^2}{(A^2-\rho^2 \circ u)^2}+\frac{2\Vert du\Vert^2~\partial_{\tau} (\rho^2 \circ u)}{(A^2-\rho^2 \circ u)^3}.
\end{align*}
It follows that
\begin{align*}
(\Delta+\partial_{\tau}) w-\frac{2g(\nabla w,\nabla (\rho^2\circ u))}{A^2-\rho^2 \circ u}&=\frac{2\Vert du\Vert^2~ (\Delta+\partial_{\tau}) (\rho^2 \circ u)}{(A^2-\rho^2 \circ u)^3}+\frac{(\Delta+\partial_{\tau}) \Vert du\Vert^2}{(A^2-\rho^2 \circ u)^2}\\
                &\quad +\frac{2g(\nabla \Vert du\Vert^2,\nabla (\rho^2 \circ u))}{(A^2-\rho^2 \circ u)^3}+\frac{2\Vert \nabla (\rho^2 \circ u) \Vert^2~\Vert du\Vert^2}{(A^2-\rho^2 \circ u)^4}.
\end{align*}
Since $(N,\mathfrak{g})$ is simply connected and $\sec \leq 0$,
the Greene-Wu Hessian comparison yields the following (see e.g., \cite[(1.263)]{AMR}, and also \cite[(1.181)]{AMR}):
\begin{equation*}
(\Delta+\partial_{\tau}) (\rho^2 \circ u)=\sum^{m}_{i=1}\nabla^2 \rho^2(du(e_i),du(e_i))\geq 2\Vert du\Vert^2,
\end{equation*}
where we also used the backward harmonic map heat flow equation \eqref{eq:bHMHF}.
Furthermore,
in view of Lemma \ref{lem:easy} and $\sec \leq 0$,
\begin{equation*}
(\Delta+\partial_{\tau}) \Vert du\Vert^2 \geq 2\Vert \nabla du\Vert^2+2\sum^{m}_{i=1}\mathfrak{g}(du(\mathcal{R}(e_i)),du(e_i)).
\end{equation*}
Combining the above estimates,
we see
\begin{align*}
(\Delta+\partial_{\tau}) w-\frac{2g(\nabla w,\nabla (\rho^2\circ u))}{A^2-\rho^2 \circ u}&\geq 4(A^2-\rho^2 \circ u)w^2\\
      &\quad+\frac{2}{(A^2-\rho^2 \circ u)^2}\sum^{m}_{i=1}\mathfrak{g}(du(\mathcal{R}(e_i)),du(e_i))+2\mathcal{F},
\end{align*}
where
\begin{equation*}
\mathcal{F}:=\frac{\Vert \nabla du\Vert^2}{(A^2-\rho^2 \circ u)^2}+\frac{\Vert \nabla (\rho^2 \circ u) \Vert^2~\Vert du\Vert^2}{(A^2-\rho^2 \circ u)^4}+\frac{g(\nabla \Vert du\Vert^2,\nabla (\rho^2 \circ u))}{(A^2-\rho^2 \circ u)^3}.
\end{equation*}

Now,
it suffices to check that
$\mathcal{F}$ is non-negative.
For the first two terms,
the inequality of arithmetic-geometric means, and the Kato inequality imply
\begin{align*}
\frac{\Vert \nabla du\Vert^2}{(A^2-\rho^2 \circ u)^2}+\frac{\Vert \nabla (\rho^2 \circ u) \Vert^2~\Vert du\Vert^2}{(A^2-\rho^2 \circ u)^4}
&\geq \frac{2\Vert \nabla du\Vert \Vert \nabla (\rho^2 \circ u) \Vert \Vert du\Vert }{(A^2-\rho^2 \circ u)^3}\\
&\geq \frac{\Vert \nabla \Vert du\Vert^2 \Vert~\Vert \nabla (\rho^2 \circ u)\Vert }{(A^2-\rho^2 \circ u)^3}.
\end{align*}
The Cauchy-Schwarz inequality tells us the desired conclusion.

\label{lem:cutoff}
Let $R,T>0,\,\alpha \in (0,1)$.
Then there is a smooth function $\psi:[0,\infty)\times [0,\infty)\to [0,1]$ which is supported on $[0,R]\times [0,T]$,
and a constant $C_\alpha>0$ depending only on $\alpha$ such that the following hold:
\begin{enumerate}\setlength{\itemsep}{3pt}
\item $\psi\equiv 1$ on $[0,R/2]\times [0,T/4]$;
\item $\partial_r \psi \leq 0$ on $[0,\infty)\times [0,\infty)$, and $\partial_r \psi \equiv 0$ on $[0,R/2]\times [0,\infty)$;
\item we have
\begin{equation*}
         \frac{\vert \partial_r \psi \vert}{\psi^\alpha}\leq \frac{C_{\alpha}}{R},\quad \frac{\vert \partial^2_{r}\psi\vert}{\psi^\alpha}\leq \frac{C_{\alpha}}{R^2},\quad \frac{\vert \partial_{\tau} \psi\vert}{\psi^{1/2}}\leq \frac{C}{T},
\end{equation*}
where $C>0$ is a universal constant.
\end{enumerate}

\label{prop:difficult}
Let $K\geq 0$.
We assume
\begin{equation*}\label{eq:cutoff assumption}
\mathcal{R}(V)\geq -K\Vert V \Vert^2,\quad \mathcal{D}(V)\geq -2K\left(H+\Vert V \Vert^2 \right),\quad \mathcal{H}(V) \geq -\frac{H}{\tau},\quad H\geq 0
\end{equation*}
for all vector fields $V$.
Let $(N,\mathfrak{g})$ be simply connected, and $\sec \leq 0$.
Let $u:M\times [0,\infty)\to N$ be a solution to backward harmonic map heat flow.
For $R,T>0$ and $A>0$,
we suppose $2\rho \circ u\leq A$ on $Q_{R,T}$.
We define $w$ as \eqref{eq:key function} on $Q_{R,T}$.
We also take a function $\psi:[0,\infty)\times [0,\infty)\to [0,1]$ in Lemma \ref{lem:cutoff} with $\alpha=3/4$,
and set
\begin{equation}\label{eq:cutoff function}
\psi(x,\tau):=\psi(\mathfrak{d}(x,\tau),\tau).
\end{equation}
Then we have
\begin{equation*}
(\psi w)^2\leq \frac{1}{A^4}\left(\frac{\overline{C}_m}{R^4}+\frac{\widetilde{C}_1}{T^2}+\widetilde{C}_2 K^2\right)+\frac{1}{A^2}\Phi.
\end{equation*}
at every point in $Q_{R,T}$ such that the reduced distance is smooth,
where for the universal constants $C_{3/4},C>0$ given in Lemma \ref{lem:cutoff},
we put
\begin{align}\label{eq:dimension epsilon}
\overline{C}_{m}&:=6C^2_{3/4}\left(m^2+\frac{9}{4}+\frac{369}{32}C^2_{3/4}\right),\quad \widetilde{C}_1:=\frac{3}{2}C^2,\quad \widetilde{C}_2:=6\left(1+\frac{C^2_{3/4}}{4}\right), \\  \label{eq:maximal constant}
\Phi&:=(\Delta+\partial_{\tau})(\psi w)-\frac{2g\left( \nabla\psi, \nabla(\psi w) \right)}{\psi}-\frac{2g(\nabla(\psi w),\nabla (\rho^2 \circ u))}{A^2-\rho^2\circ u}.
\end{align}

In virtue of Lemma \ref{lem:simple},
\begin{align*}
\Phi&=\psi \left(\Delta+\partial_{\tau} \right)w-\frac{2\psi g(\nabla w,\nabla (\rho^2\circ u))}{A^2-\rho^2 \circ u}
+w\left(\Delta+\partial_{\tau}\right)\psi-\frac{2w\Vert \nabla \psi \Vert^2}{\psi}-\frac{2w g(\nabla \psi,\nabla (\rho^2\circ u))}{A^2-\rho^2 \circ u}\\
    &\geq 4(A^2-\rho^2 \circ u)\psi w^2+\frac{2\psi }{(A^2-\rho^2 \circ u)^2}\sum^{m}_{i=1}\mathfrak{g}(du(\mathcal{R}(e_i)),du(e_i))
    +w\left(\Delta+\partial_{\tau} \right)\psi-\frac{2w\Vert \nabla \psi \Vert^2}{\psi}\\
    &\qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad\qquad \quad \, -2\frac{w g(\nabla \psi,\nabla (\rho^2\circ u))}{A^2-\rho^2 \circ u}.
\end{align*}
It follows that
\begin{equation}\label{eq:main difficult}
4(A^2-\rho^2 \circ u)\psi w^2 \leq \Psi_1+\Psi_2+\Psi_3+\Psi_4+\Phi
\end{equation}
for
\begin{align*}
\Psi_1&:=-\frac{2\psi }{(A^2-\rho^2 \circ u)^2}\sum^{m}_{i=1}\mathfrak{g}(du(\mathcal{R}(e_i)),du(e_i)),\quad \Psi_2:=-w \left(\Delta+\partial_{\tau}\right)\psi,\\ \Psi_3&:=\frac{2w\Vert \nabla \psi \Vert^2}{\psi},\quad \Psi_4:=\frac{2w g(\nabla \psi,\nabla (\rho^2\circ u))}{A^2-\rho^2 \circ u}.
\end{align*}

We provide upper bounds of $\Psi_1, \Psi_2, \Psi_3,\Psi_4$.
The following Young inequality plays a crucial role:
For all $p,q\in (1,\infty)$ with $p^{-1}+q^{-1}=1$, $a,b\geq 0$, and $\varepsilon>0$,
\begin{equation}\label{eq:Young}
ab\leq \frac{\varepsilon a^p}{p}+\frac{b^q}{\varepsilon^{q/p} q}.
\end{equation} 
The inequality
\begin{equation}\label{eq:grad est cutoff}
\frac{\Vert \nabla \psi \Vert^2}{\psi^{3/2}}\leq \frac{3 C^2_{3/4}}{R^2}
\end{equation}
is also useful,
which follows from Lemmas \ref{lem:reduced gradient estimate} and \ref{lem:cutoff}.
We first study an upper bound of $\Psi_1$.
By the assumption for $\mathcal{R}(V)$,
the Young inequality \eqref{eq:Young} with $p,q=2$,
and $\psi\leq 1$,
\begin{equation}\label{eq:estimate of C_1}
\Psi_1=-\frac{2\psi }{(A^2-\rho^2 \circ u)^2}\sum^{m}_{i=1}\mathfrak{g}(du(\mathcal{R}(e_i)),du(e_i)) \leq 2K \psi w\leq \varepsilon \psi^2 w^2+\frac{K^2}{\varepsilon}\leq \varepsilon \psi w^2+\frac{K^2}{\varepsilon}.
\end{equation}
We next produce an upper bound of $\Psi_2$.
We see
\begin{align*}
\Psi_2&=-w \left(\Delta+\partial_{\tau}\right)\psi=-w  \left(           \partial_r \psi(\Delta+\partial_{\tau})\mathfrak{d}+\partial^2_r \psi \Vert \nabla \mathfrak{d} \Vert^2+\partial_{\tau} \psi \right)\\ \notag
                  &=-w  \left[           \partial_r \psi   \left(  \frac{1}{2\mathfrak{d}}(\Delta+\partial_{\tau})\overline{L}-\frac{\Vert \nabla \overline{L} \Vert^2}{4\mathfrak{d}^3}  \right)+\partial^2_r \psi \Vert \nabla \mathfrak{d} \Vert^2+\partial_{\tau} \psi \right]\\ \notag
                  &=\frac{w \vert \partial_r \psi \vert}{2\mathfrak{d}}(\Delta+\partial_{\tau})\overline{L}-w \vert \partial_r \psi \vert \frac{\Vert \nabla \overline{L} \Vert^2}{4\mathfrak{d}^3}-w \,\partial^2_r \psi \Vert \nabla \mathfrak{d} \Vert^2-w\,\partial_{\tau} \psi\\ \notag
                  & \leq \frac{w \vert \partial_r \psi \vert}{2\mathfrak{d}}(\Delta+\partial_{\tau})\overline{L}+w \vert \partial^2_r \psi\vert \Vert \nabla \mathfrak{d} \Vert^2+w \,\vert \partial_{\tau} \psi \vert.
\end{align*}
Lemmas \ref{lem:reduced heat estimate2}, \ref{lem:reduced gradient estimate} and $\overline{L}=\mathfrak{d}^2$ yield
\begin{align*}
\Psi_2&\leq m \frac{w \vert \partial_r \psi \vert}{\mathfrak{d}}+K w \vert \partial_r \psi \vert \mathfrak{d}+3w \vert \partial^2_r \psi \vert+w \, \vert \partial_{\tau} \psi \vert \\ \notag
                       &\leq \frac{2m}{R} w \vert \partial_r \psi \vert+KR w \vert \partial_r \psi \vert+3w \vert \partial^2_r \psi \vert+w \,\vert \partial_{\tau} \psi \vert,
\end{align*}
where in the second inequality,
we used the fact that
$\partial_r \psi$ vanishes on $[0,R/2]\times [0,\infty)$.
From the Young inequality \eqref{eq:Young} with $p,q=2$,
Lemma \ref{lem:cutoff},
and $\psi\leq 1$,
we derive
\begin{align}\label{eq:estimate of A}
\Psi_2&\leq \left( \varepsilon  \psi w^2+\frac{m^2}{R^2}\frac{ \vert \partial_r \psi \vert^2}{\varepsilon  \psi}   \right)
+\left( \varepsilon \psi w^2+\frac{K^2 R^2}{4}\frac{ \vert \partial_r \psi \vert^2}{\varepsilon \psi}   \right)\\ \notag
&\qquad \qquad \qquad \qquad \qquad \,\,\,+\left( \varepsilon \psi w^2+\frac{9}{4}\frac{ \vert \partial^2_r \psi \vert^2}{\varepsilon \psi}   \right)
+\left( \varepsilon \psi w^2+\frac{1}{4}\frac{ \vert \partial_{\tau}  \psi\vert^2}{\varepsilon \psi}   \right) \\ \notag
&\leq 4\varepsilon  \psi w^2+\frac{C^2_{3/4}}{\varepsilon}\left(m^2+\frac{9}{4}\right)\frac{ \psi^{1/2}}{R^4}+\frac{C^2}{4\varepsilon}\frac{1}{T^2}+\frac{C^2_{3/4}}{4\varepsilon}K^2\psi^{1/2}\\ \notag
&\leq 4\varepsilon  \psi w^2+\frac{C^2_{3/4}}{\varepsilon}\left(m^2+\frac{9}{4}\right)\frac{1}{R^4}+\frac{C^2}{4\varepsilon}\frac{1}{T^2}+\frac{C^2_{3/4}}{4\varepsilon}K^2.
\end{align}
We give an upper bound of $\Psi_3$.
By the Young inequality \eqref{eq:Young} with $p,q=2$,
and \eqref{eq:grad est cutoff},
\begin{equation}\label{eq:estimate of B}
\Psi_3= \frac{2w\Vert \nabla \psi \Vert^2}{\psi} \leq \varepsilon \psi w^2+\frac{\Vert \nabla \psi \Vert^4}{\varepsilon \psi^3}\leq \varepsilon \psi w^2+\frac{9C^4_{3/4}}{\varepsilon}\frac{1}{R^4}.
\end{equation}
We finally examine $\Psi_4$.
The Cauchy-Schwarz inequality,
the Young inequality (\ref{eq:Young}) with $p=4/3,q=4,\varepsilon=4/3$,
and \eqref{eq:grad est cutoff} lead us to
\begin{align}\label{eq:estimate of C}
\Psi_4&=2\frac{w g(\nabla \psi,\nabla (\rho^2\circ u))}{A^2-\rho^2 \circ u}\leq \frac{2w\Vert \nabla \psi \Vert \Vert \nabla (\rho^2 \circ u) \Vert}{A^2-\rho^2 \circ u}\leq 2 A w^{3/2} \Vert \nabla \psi \Vert\\ \notag
                  &\leq A^2\psi w^2+\frac{27}{16} \frac{1}{A^2}  \frac{\Vert \nabla \psi \Vert^4}{\psi^3}\leq A^2\psi w^2+\frac{243C^4_{3/4}}{16} \,\frac{1}{A^2}\frac{1}{R^4}.
\end{align}

By summarizing (\ref{eq:main difficult}), (\ref{eq:estimate of C_1}), (\ref{eq:estimate of A}), (\ref{eq:estimate of B}), (\ref{eq:estimate of C}),
\begin{align*}
3A^2\psi w^2 &\leq 4(A^2-\rho^2 \circ u)\psi w^2\\
&\leq (6\varepsilon+A^2)  \psi w^2+\frac{C^2_{3/4}}{\varepsilon}\left(m^2+\frac{9}{4}+9C^2_{3/4}+  \frac{243 \varepsilon C^2_{3/4}}{16} \,\frac{1}{A^2}   \right)\frac{1}{R^4}\\
&\qquad \qquad \qquad \quad \, \,+\frac{C^2}{4\varepsilon}\frac{1}{T^2}+\frac{1}{\varepsilon}\left(1+\frac{C^2_{3/4}}{4}\right)K^2+\Phi.
\end{align*}
 Letting $\varepsilon \to A^2/6$,
we have
\begin{equation*}
\psi w^2 \leq \frac{1}{A^4}\left(\frac{\overline{C}_m}{R^4}+\frac{\widetilde{C}_1}{T^2}+\widetilde{C}_2 K^2\right)+\frac{1}{A^2}\Phi.
\end{equation*}
Since $(\psi w)^2\leq \psi w^2$,
we arrive at the desired inequality.

\label{cor:cor1}
Let $(M,g(\tau))_{\tau \in [0,\infty)}$ be a complete backward Ricci flow with bounded, non-negative curvature operator.
Let $(N,\mathfrak{g})$ be a complete, simply connected Riemannian manifold with $\sec \leq 0$.
Let $u:M\times [0,\infty)\to N$ be a solution to backward harmonic map heat flow.
If
\begin{equation*}
\rho(u(x,\tau))=o\left(\mathfrak{d}(x,\tau)+\sqrt{\tau}\right)
\end{equation*}
near infinity, then $u$ is constant.

\label{thm:gradient2}
For $K\geq 0$,
let $(M,g(\tau))_{\tau \in [0,\infty)}$ be an $m$-dimensional, admissible, complete backward $(-K)$-super Ricci flow.
We assume 
\begin{equation}\label{eq:Kmain assumption2}
\mathcal{D}(V)\geq -2K\left(H+\Vert V\Vert^2   \right),\quad \mathcal{H}(V) \geq -\frac{H}{\tau},\quad H\geq 0
\end{equation}
for all vector fields $V$.
Let $(N,\mathfrak{g})$ denote a complete Riemannian manifold with $\sec \leq \kappa$ for $\kappa>0$.
Assume that $B_{\pi/2\sqrt{\kappa}}(y_0)$ does not meet $\mathrm{Cut}\,(y_0)$.
Let $u:M\times [0,\infty)\to N$ be a solution to backward harmonic map heat flow.
Suppose that the image of $u$ is contained in $B_{\pi/2\sqrt{\kappa}}(y_0)$.
For $R,T>0$,
let
\begin{equation}\label{eq:new key function}
\varphi:=1-\cos \sqrt{\kappa}\rho,\quad A:=\frac{1}{2}\left(1+\sup_{Q_{R,T}}\varphi \circ u  \right).
\end{equation}
Then there is a positive constant $C_{m}>0$ depending only on $m$ such that on $Q_{R/2,T/4}$,
\begin{equation*}
\frac{\Vert du \Vert}{A-\varphi \circ u}\leq \frac{C_{m}}{\sqrt{\kappa}} \left( \frac{1}{R}+\frac{1}{\sqrt{T}}+\sqrt{K}  \right)\sup_{Q_{R,T}}\left(\frac{1}{\cos\sqrt{\kappa}\rho \circ u}\right)^2.
\end{equation*}

\label{lem:simple2}
Let $(N,\mathfrak{g})$ be $\sec \leq \kappa$ for $\kappa>0$.
Assume that $B_{\pi/2\sqrt{\kappa}}(y_0)$ does not meet $\mathrm{Cut}\,(y_0)$.
Let $u:M\times [0,\infty)\to N$ be a solution to backward harmonic map heat flow.
Suppose that the image of $u$ is contained in $B_{\pi/2\sqrt{\kappa}}(y_0)$.
For $R,T>0$,
we define $\varphi$ and $A$ as \eqref{eq:new key function}.
Set
\begin{equation}\label{eq:key function2}
w:=\frac{\Vert du\Vert^2}{(A-\varphi \circ u)^2}.
\end{equation}
Then we have
\begin{align*}
(\Delta+\partial_{\tau}) w-2\frac{g(\nabla w,\nabla (\varphi \circ u))}{A-\varphi \circ u}&\geq 2\kappa(1-A)(A-\varphi \circ u)w^2\\
      &\quad +\frac{2}{(A-\varphi \circ u)^2}\sum^{m}_{i=1}\mathfrak{g}(du(\mathcal{R}(e_i)),du(e_i)).
\end{align*}

By similar computations to the proof of Lemma \ref{lem:simple},
we see
\begin{align*}
(\Delta+\partial_{\tau}) w &=\frac{2g(\nabla w,\nabla (\varphi\circ u))}{A-\varphi \circ u}+\frac{2\Vert du\Vert^2~ (\Delta+\partial_{\tau}) (\varphi \circ u)}{(A-\varphi \circ u)^3}+\frac{(\Delta+\partial_{\tau}) \Vert du\Vert^2}{(A-\varphi \circ u)^2}\\
                &\quad+\frac{2g(\nabla \Vert du\Vert^2,\nabla (\varphi \circ u))}{(A-\varphi \circ u)^3}+\frac{2\Vert \nabla (\varphi \circ u) \Vert^2~\Vert du\Vert^2}{(A-\varphi \circ u)^4}.
\end{align*}
Due to the Hessian comparison,
\begin{equation*}
(\Delta+\partial_{\tau}) (\varphi \circ u)=\sum^{m}_{i=1}\nabla^2 \rho^2(du(e_i),du(e_i))\geq \kappa \cos\sqrt{\kappa}\rho \circ u \Vert du \Vert^2.
\end{equation*}
Furthermore,
Lemma \ref{lem:easy} and $\sec \leq \kappa$ lead us to
\begin{equation*}
(\Delta+\partial_{\tau}) \Vert du\Vert^2 \geq 2\Vert \nabla du\Vert^2+2\sum^{m}_{i=1}\mathfrak{g}(du(\mathcal{R}(e_i)),du(e_i))-2\kappa \Vert du \Vert^4.
\end{equation*}
It holds that
\begin{align*}
(\Delta+\partial_{\tau}) w-\frac{2g(\nabla w,\nabla (\varphi \circ u))}{A-\varphi \circ u}&\geq 2\kappa(A-\varphi \circ u)^2 \left( \frac{\cos \sqrt{\kappa}\rho }{A-\varphi \circ u}-1   \right) w^2\\
      &\quad +\frac{2}{(A-\varphi \circ u)^2}\sum^{m}_{i=1}\mathfrak{g}(du(\mathcal{R}(e_i)),du(e_i))+2\mathcal{F}\\
      &= 2\kappa(1-A)(A-\varphi \circ u)w^2\\
      &\quad +\frac{2}{(A-\varphi \circ u)^2}\sum^{m}_{i=1}\mathfrak{g}(du(\mathcal{R}(e_i)),du(e_i))+2\mathcal{F},
\end{align*}
where
\begin{equation*}
\mathcal{F}:=\frac{\Vert \nabla du\Vert^2}{(A-\varphi \circ u)^2}+\frac{\Vert \nabla (\varphi \circ u) \Vert^2~\Vert du\Vert^2}{(A-\varphi \circ u)^4}+\frac{g(\nabla \Vert du\Vert^2,\nabla (\varphi \circ u))}{(A-\varphi \circ u)^3}.
\end{equation*}
By similar computations to the proof of Lemma \ref{lem:simple},
$\mathcal{F}$ is non-negative.

Using Lemma \ref{lem:simple2},
we see
\begin{align*}
\Phi&=\psi \left(\Delta+\partial_{\tau} \right)w-\frac{2\psi g(\nabla w,\nabla (\varphi\circ u))}{A-\varphi \circ u}
+w\left(\Delta+\partial_{\tau}\right)\psi-\frac{2w\Vert \nabla \psi \Vert^2}{\psi}-\frac{2w g(\nabla \psi,\nabla (\varphi \circ u))}{A-\varphi \circ u}\\
    &\geq 2\kappa(1-A)(A-\varphi \circ u)\psi w^2+\frac{2\psi }{(A-\varphi \circ u)^2}\sum^{m}_{i=1}\mathfrak{g}(du(\mathcal{R}(e_i)),du(e_i))
    +w\left(\Delta+\partial_{\tau} \right)\psi\\
    &\qquad \qquad \qquad \qquad \qquad \qquad \,\,~  -\frac{2w\Vert \nabla \psi \Vert^2}{\psi}-2\frac{w g(\nabla \psi,\nabla (\varphi\circ u))}{A-\varphi \circ u}.
\end{align*}
We obtain
\begin{equation*}
2\kappa(1-A)(A-\varphi \circ u)\psi w^2 \leq \Psi_1+\Psi_2+\Psi_3+\Psi_4+\Phi
\end{equation*}
for
\begin{align*}
\Psi_1&:=-\frac{2\psi }{(A-\varphi \circ u)^2}\sum^{m}_{i=1}\mathfrak{g}(du(\mathcal{R}(e_i)),du(e_i)),\quad \Psi_2:=-w \left(\Delta+\partial_{\tau}\right)\psi,\\ \Psi_3&:=\frac{2w\Vert \nabla \psi \Vert^2}{\psi},\quad \Psi_4:=\frac{2w g(\nabla \psi,\nabla (\varphi\circ u))}{A-\varphi \circ u}.
\end{align*}
For $\Psi_1$,
the following holds:
\begin{equation*}
\Psi_1=-\frac{2\psi }{(A-\varphi \circ u)^2}\sum^{m}_{i=1}\mathfrak{g}(du(\mathcal{R}(e_i)),du(e_i)) \leq 2K \psi w\leq \varepsilon \psi^2 w^2+\frac{K^2}{\varepsilon}\leq \varepsilon \psi w^2+\frac{K^2}{\varepsilon}
\end{equation*}
in the same manner as in the proof of Proposition \ref{prop:difficult}.
For $\Psi_2,\Psi_3$,
we possess the same upper estimates as in the proof of Proposition \ref{prop:difficult}.
For $\Psi_4$,
the following holds:
\begin{align*}\label{eq:estimate of C2}
\Psi_4&=\frac{2w g(\nabla \psi,\nabla (\varphi \circ u))}{A-\varphi \circ u}\leq \frac{2w\Vert \nabla \psi \Vert \Vert \nabla (\varphi \circ u) \Vert}{A-\varphi \circ u}\leq 2 \sqrt{\kappa} w^{3/2} \Vert \nabla \psi \Vert\\ \notag
                  &\leq \frac{3 \varepsilon}{4}\psi w^2+\frac{4\kappa^2}{\varepsilon^3}  \frac{\Vert \nabla \psi \Vert^4}{\psi^3}\leq \frac{3 \varepsilon}{4}\psi w^2+\frac{36\kappa^2C^4_{3/4}}{\varepsilon^3} \,\frac{1}{R^4}.
\end{align*}
This proves the desired estimate.

\label{lem:ref-kato}
For a harmonic map $u: M \to N$, we have 
\begin{equation}\label{eq:ref-kato}
\Vert\nabla \Vert du\Vert\Vert^2\leq \frac{m-1}{m}\Vert\nabla du\Vert^2.   
\end{equation}

It is enough to show the inequality at $x_0\in M$ such that $\Vert du \Vert(x_0)\neq 0$. Let us fix such a point. We compute in normal coordinates $(x^i)=(x^1, \dots, x^m)$ around $x_0\in M$ and $(y^\alpha)=(y^1, \dots, y^n)$ around $u(x_0)\in N$. Let $u(x)=(u^1(x^1, \dots, x^m), \dots, u^n(x^1, \dots, x^m))$ be the local expression for $u:M\to N$ in these coordinates. We use the notations 	
\begin{equation*}
	u^\alpha_i=\frac{\partial u^\alpha}{\partial x^i}, \quad \text{and} \quad u^\alpha_{ij}=\frac{\partial^2u^\alpha}{\partial x^i\partial x^j}. 
\end{equation*}
Now we can write   
\begin{equation*}
	\Vert \nabla du \Vert^2(x_0)=\sum_{\alpha=1}^n \sum_{i,j=1}^m (u_{ij}^\alpha)^2(x_0) 
\end{equation*}
at $x_0\in M$. For any $1\leq \alpha\leq n$, let $\lambda^\alpha_1, \dots, \lambda^\alpha_m$ be real eigenvalues of the symmetric matrix $(u^\alpha_{ij}(x_0))$ such that $|\lambda^\alpha_1|\leq \cdots \leq |\lambda^\alpha_m|$. Then we have 
\begin{equation*}
	\Vert \nabla du \Vert^2(x_0)=\sum_{\alpha=1}^n \sum_{i=1}^m(\lambda^\alpha_i)^2. 
\end{equation*}
On the other hand, since $u:M\to N$ is a harmonic map, we have 
\begin{equation*}
	\sum_{i=1}^m u_{ii}^\alpha(x_0)=\sum_{i=1}^m \lambda_i^\alpha=0 \quad \text{for all} \quad 1\leq \alpha \leq n. 
\end{equation*} 
Using this, elementary computation yields 
\begin{equation*}
	\sum_{i=1}^{m-1}(\lambda_i^\alpha)^2\geq \frac{1}{m-1}\left(\sum_{i=1}^{m-1}\lambda_i^\alpha \right)^2=\frac{1}{m-1}(\lambda^{\alpha}_m)^2 \quad \text{for all} \quad 1\leq \alpha \leq n. 
\end{equation*}
Adding $(\lambda^\alpha_m)^2$ to the both sides of this inequality, we have 
\begin{equation*}
\Vert \nabla^2u^\alpha \Vert^2(x_0)=\sum_{i=1}^{m}(\lambda_i^\alpha)^2\geq \frac{m}{m-1}(\lambda^\alpha_m)^2 \quad \text{for all} \quad 1\leq \alpha \leq n. 
\end{equation*}
For a general $m\times m$ symmetric matrix $A$ which has real eigenvalues $\lambda_1, \dots, \lambda_m$ with $|\lambda_1|\leq \cdots \leq |\lambda_m|$, and a vector $v\in \mathbb{R}^m$, it holds that 
\begin{equation*}
	\Vert Av\Vert^2\leq |\lambda_m|^2 \Vert v\Vert^2.  
\end{equation*}
In our case, for each $1\leq \alpha \leq n$, put $v=\nabla u^\alpha(x_0)$ and $A=(u^\alpha_{ij}(x_0))$, then we have  
\begin{align*}
\Vert \nabla u^\alpha \Vert^2(x_0)\Vert \nabla^2 u^\alpha \Vert^2(x_0) &= \Vert  \nabla u^\alpha \Vert^2(x_0) \sum_{i=1}^m(\lambda^\alpha_i)^2\\ 
&\geq \frac{m}{m-1}\Vert \nabla u^\alpha \Vert^2(x_0)|\lambda^\alpha_m|^2\\
&\geq \frac{m}{m-1}\sum_{i=1}^m\left(\sum_{j=1}^m u_{ij}^\alpha(x_0) u_j^\alpha(x_0)\right)^2. 
\end{align*}
Therefore, using the Cauchy-Schwarz inequality and the Minkowski inequality, we have 
\begin{align*}
\Vert du \Vert^2(x_0) \Vert \nabla du \Vert^2(x_0)&=\left(\sum_{\alpha=1}^n \Vert \nabla u^\alpha \Vert^2(x_0)\right)\left(\sum_{\alpha=1}^n\Vert\nabla^2 u^\alpha \Vert^2(x_0)\right)\\
&\geq \left(\sum_{\alpha=1}^n\Vert\nabla u^\alpha\Vert(x_0)\Vert \nabla^2 u^\alpha \Vert(x_0) \right)^2\\
&\geq \frac{m}{m-1}\left[ \sum_{\alpha=1}^n\left\{\sum_{i=1}^m\left(\sum_{j=1}^m u_{ij}^\alpha(x_0) u_j^\alpha(x_0)\right)^2 \right\}^{\frac{1}{2}}\right]^2\\
&\geq \frac{m}{m-1}\sum_{i=1}^m\left(\sum_{\alpha=1}^n\sum_{j=1}^m u_{ij}^\alpha(x_0) u_j^\alpha(x_0)\right)^2. 
\end{align*}
Note that 
\begin{equation*}
4\Vert du \Vert^2 \Vert \nabla\Vert du\Vert \Vert^2 = \Vert \nabla \Vert du \Vert^2 \Vert^2=4\sum_{i=1}^m\left(\sum_{\alpha=1}^n\sum_{j=1}^m u_{ij}^\alpha u_j^\alpha\right)^2. 
\end{equation*}
Hence we obtain 
\begin{equation*}
\Vert du \Vert^2(x_0) \Vert \nabla du \Vert^2(x_0)\geq \frac{m}{m-1}\Vert du \Vert^2(x_0) \Vert \nabla\Vert du\Vert \Vert^2(x_0). 
\end{equation*}
This completes the proof of Lemma \ref{lem:ref-kato}.

The Bochner formula for a harmonic map $u:M\to N$ (i.e., harmonic map version of Lemma \ref{lem:easy}) combined with the refined Kato inequality \eqref{eq:ref-kato} and curvature assumptions on $M, N$ tells us that 
\begin{equation}\label{eq:bochner-kato}
\Delta\Vert du\Vert^2\geq -2\kappa \Vert du\Vert^4+2\Vert\nabla du\Vert^2 \geq -2\kappa \Vert du\Vert^4+\frac{2m}{m-1}\Vert\nabla \Vert du\Vert\Vert^2. 
\end{equation}
Let $v(x)=1/\cos\sqrt{\kappa}\rho(u(x))$. Note that this is well-defined when $u(M)\subset B_{\pi/2\sqrt{\kappa}}(y_0)$. The Hessian comparison theorem under the curvature assumption on $N$ implies 
\begin{equation}\label{eq:lap-v}
	\Delta v=v^2\Delta(\varphi\circ u)+\frac{2\Vert\nabla v\Vert^2}{v}\geq \kappa \Vert du\Vert^2v+\frac{2\Vert\nabla v\Vert^2}{v}, 
\end{equation}
where $\varphi=1-\cos\sqrt \kappa\rho$. Using \eqref{eq:bochner-kato} and \eqref{eq:lap-v}, a direct computation yields 
\begin{align*}
\Delta(\Vert du\Vert^p v^q)&\geq \kappa(q-p)\Vert du\Vert^{p+2}v^q\\
	&+p\left(p-1+\frac{1}{m-1}\right)\Vert du\Vert^{p-2}v^q\Vert\nabla\Vert du\Vert\Vert^2+q(q+1)\Vert du\Vert^p v^{q-2}\Vert\nabla v\Vert^2\\&+2pq\Vert du\Vert^{p-1}v^{q-1}g(\nabla\Vert du\Vert, \nabla v), 
\end{align*}
where $p, q$ are determined later. 
Using the Cauchy-Schwarz inequality and the Young inequality (with $\varepsilon>0$) for the last term, we have 
\begin{align}\label{eq:main-ineq}
\Delta(\Vert du\Vert^p v^q)&\geq \kappa(q-p)\Vert du\Vert^{p+2}v^q \\
	&\quad +p\left(p-1+\frac{1}{m-1}-\varepsilon q \right)\Vert du\Vert^{p-2}v^q
	\Vert \nabla\Vert du\Vert \Vert^2  \nonumber \\
	&\quad +q\left(q+1-\varepsilon^{-1}p\right)\Vert du\Vert^p v^{q-2}\Vert\nabla v\Vert^2. \nonumber
\end{align}
For given $m\geq 2$, let $q=p>2m-3$ and $\varepsilon=q/(q+1)$. Then we have 
\begin{equation*}
\Delta(\Vert du\Vert^q v^q)\geq 0,  
\end{equation*}
i.e., $\Vert du\Vert^q v^q$ is a subharmonic function on $M$. Therefore, we can use Li-Schoen's mean value inequality (see e.g., \cite[Theorem 7.2]{PLi}) to conclude 
\begin{equation}\label{eq:mean value ineq}
\sup_{B_{R/4}(x_0)}\Vert du\Vert^{2q} v^{2q}\leq \frac{C_m}{\operatorname{vol}({B_{R}(x_0))}}\int_{B_{R}(x_0)}\Vert du\Vert^{2q}v^{2q},  
\end{equation} 
where $C_m$ is a positive constant depending only on $m$.

On the other hand, choosing $q=p+1>2m-3$ and $\varepsilon=(q-1)/(q+1)$ in \eqref{eq:main-ineq}, we have  
\begin{equation*}
\Delta(\Vert du\Vert^{q-1}v^q) \geq \kappa \Vert du\Vert^{q+1}v^q. 
\end{equation*}
We multiply this by $\Vert du\Vert^{q-1}v^q\eta^{2q}$, where $\eta$ is a test function on $M$ with compact support, and then integrating by parts with the Cauchy-Schwarz inequality and the Young inequality yields 
\begin{align*}
\kappa\int_{M}\Vert du\Vert^{2q}v^{2q}\eta^{2q}\leq \frac{1}{2}\int_{M}\Vert du\Vert^{2q-2}v^{2q}\eta^{2q-2}\Vert\nabla \eta\Vert^2.  
\end{align*}
Recall the generalized Young inequality for $a, b\geq 0$ with arbitrary $\varepsilon>0$:
\begin{equation*}
ab\leq \varepsilon\left(\frac{q-1}{q}\right)a^{q/(q-1)}+\frac{\varepsilon^{-(q-1)}}{q}b^q.  
\end{equation*}
Putting $a=\Vert du \Vert^{2q-2}\eta^{2q-2}$ and $b=\Vert \nabla\eta\Vert^2$ in this inequality, we have 
\begin{equation*}
\left(\kappa-\frac{\varepsilon(q-1)}{2q}\right)\int_{M}\Vert du\Vert^{2q}v^{2q}\eta^{2q}\leq \frac{\varepsilon^{-(q-1)}}{2q}\int_{M}v^{2q}\Vert \nabla \eta\Vert^{2q}. 
\end{equation*}
We take $\varepsilon=\kappa q/(q-1)$ to get 
\begin{equation*}
	\int_{M}\Vert du \Vert^{2q}v^{2q}\eta^{2q}\leq \frac{(q-1)^{q-1}}{\kappa^q q^q}\int_{M}v^{2q}\Vert \nabla \eta\Vert^{2q}. 
\end{equation*} 
Choosing $\eta$ as the standard cut-off function in this inequality, we obtain 
\begin{align}\label{eq:ineq-cutoff}
\int_{B_{R}(x_0)}\Vert du\Vert^{2q}v^{2q}&\leq \frac{(q-1)^{q-1}}{\kappa^q q^q R^{2q}} \int_{B_{2R}(x_0)}v^{2q} \\ \notag
&\leq \frac{(q-1)^{q-1}}{\kappa^q q^q R^{2q}}\operatorname{vol}(B_{2R}(x_0))\sup_{B_{2R}(x_0)}v^{2q}.
\end{align} 
Combining \eqref{eq:mean value ineq}, \eqref{eq:ineq-cutoff} and the Bishop-Gromov volume comparison, it follows that \begin{equation*}
\sup_{B_{R/4}(x_0)}\Vert du\Vert v\leq \left(\frac{C_m(q-1)^{q-1}}{\kappa^q q^q R^{2q}}\right)^{1/2q} \left( \frac{\operatorname{vol}(B_{2R}(x_0))}{\operatorname{vol}(B_{R}(x_0))} \right)^{1/2q}\sup_{B_{2R}(x_0)}v\leq  C_{m, \kappa, q}\frac{o(R)}{R}, 
\end{equation*}
where $C_{m,\kappa,q}$ is a positive constant depending only on $m,\,\kappa$ and $q$.
We here notice that $q$ depends only on $m$. 
Letting $R\to \infty$, we complete the proof of Theorem \ref{thm:improve}.
